// TEST verifier v6 requires a single fresh job ID and matching request ID.
// Never run a shared-queue claim on login or import. A future controlled operator
// action must receive a DB-provided exact job/request pair and explicit intent.
async function verifyExactSupplierSource(jobId,requestId){
 const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
 if(!uuid.test(String(jobId||''))||!uuid.test(String(requestId||'')))
  throw new Error('SOURCE_TARGET_REQUIRED');
 const {data,error}=await client.functions.invoke('planea-source-verifier-test',{
  body:{job_id:jobId,request_id:requestId}
 });
 if(error||data?.status!=='finished'||data?.job_id?.toLowerCase()!==jobId.toLowerCase()||
    Number(data.processed)!==1)throw new Error('VERIFIER_TEMPORARILY_UNAVAILABLE');
 return data;
}
function formData(form){return Object.fromEntries(new FormData(form));}function normalizeCandidatePackage(pkg){
 if(!pkg||pkg.contract!=='planea.provider_candidates.v1'||pkg.version!==1||!Array.isArray(pkg.candidates))return pkg;
 if(!pkg.candidates.length||pkg.candidates.some(c=>!c||typeof c!=='object'||typeof c.provider_name!=='string'||!c.provider_name.trim()||typeof c.service_category!=='string'))throw new Error('El paquete necesita proveedores con provider_name y service_category originales. Copia de nuevo el bloque JSON completo.');
 if(pkg.privacy?.customer_identity_included!==false)throw new Error('PRIVACY_VIOLATION');
 const http=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol);}catch(_){return false;}};
 const routeTypes=new Set(['whatsapp','phone','email','website','instagram','facebook','other','url','contact_form']);
 const omitted=[];
 const candidates=pkg.candidates.map(c=>{const e=c.contact_enrichment||{},inspected=Array.isArray(e.inspected_sources)?e.inspected_sources.filter(x=>typeof x==='string'&&http(x)&&x.length<=2000):[];let routes=Array.isArray(c.contact_routes)?c.contact_routes.filter(r=>{const ok=window.PLANEAContactEnrichment.routeIsSupported(c,e,r);if(!ok)omitted.push({provider_name:c.provider_name,type:r?.type||'unknown',value:r?.value||''});return ok;}).map(r=>({type:r.type,value:r.value,source_url:r.source_url,evidence:r.evidence,verified:true})):[];const official=typeof e.official_source_url==='string'?e.official_source_url:c.source_url;if(official&&!inspected.includes(official))inspected.unshift(official);const direct=routes.some(r=>['whatsapp','email','phone'].includes(r.type)),web=routes.some(r=>['website','url','contact_form'].includes(r.type));return {provider_name:c.provider_name,service_category:c.service_category,service_area:c.service_area,source_url:c.source_url,contact_routes:routes,evidence:Array.isArray(c.evidence)?c.evidence.join(' · '):String(c.evidence||''),verification_state:routes.length?'partially_verified':'unverified',contact_enrichment:{official_source_url:official,inspected_sources:inspected,direct_contact_search_completed:e.direct_contact_search_completed===true,web_only:!direct&&web}};});
 const normalized={contract:'planea.provider_candidates.v1',version:1,request_ref:pkg.request_ref,candidates,privacy:{customer_identity_included:false}};
 Object.defineProperty(normalized,'omittedContactRoutes',{value:omitted,enumerable:false});
 return normalized;
}

function friendlyError(e){const code=e?.message||String(e);if(code.includes('PROVIDER_RESPONSE_REFERENCE_MISMATCH'))return 'La respuesta pertenece a otra solicitud o proveedor. Abre la tarjeta correcta o pide a ChatGPT conservar el request_ref y candidate_ref originales; no edites IDs.';if(code.includes('CANDIDATE_MAPPING_REQUIRED')||code.includes('INVALID_CANDIDATE_REFERENCE'))return 'No se pudo atribuir el proveedor de forma única. Actualiza la solicitud y pide a ChatGPT la referencia original; no inventes IDs.';if(code.includes('UNVERIFIED_CONTACT_ROUTE'))return 'No pudimos verificar uno de los medios de contacto. El paquete no fue importado. Vuelve a procesar la búsqueda para que cada WhatsApp, correo o teléfono incluya evidencia pública del contacto exacto.';if(code.includes('CONTACT_ENRICHMENT_REQUIRED'))return 'La búsqueda no incluyó la verificación de contacto requerida. Vuelve a procesarla con el paquete original de PLANEA.';if(code.includes('CONTACT_ENRICHMENT_CLASSIFICATION_MISMATCH'))return 'La clasificación del canal de contacto no coincide con la evidencia encontrada. El paquete no fue importado.';return labels[code]||(/^[A-Z][A-Z0-9_]+$/.test(code)?'No pudimos completar esta acción. Actualiza la solicitud y vuelve a intentar. Si continúa, informa al equipo de Semblanzia.':code);}async function run(fn){message('');try{await fn();}catch(e){message(friendlyError(e)||'No pudimos completar esta acción.',true);}}
async function lock(form,fn){const controls=[...form.querySelectorAll('button')];const disabled=controls.map(b=>b.disabled);controls.forEach(b=>b.disabled=true);pendingActions++;try{await fn();}finally{pendingActions--;controls.forEach((b,i)=>b.disabled=disabled[i]);}}
function keyFor(name,data){const fingerprint=name+JSON.stringify(data);if(!retryKeys.has(fingerprint))retryKeys.set(fingerprint,crypto.randomUUID());return {fingerprint,key:retryKeys.get(fingerprint)};}
async function action(name,data){const retry=keyFor(name,{request:active,data});await rpc('planea_operator_action',{p_action:name,p_request:active,p_data:data,p_key:retry.key});retryKeys.delete(retry.fingerprint);await detail(active,{scroll:false});await refresh();}
// Customer requests are independent expandable cards. Keep one trusted detail renderer
// and move its DOM inside the currently open request, never below the entire list.
function attachCustomerRequest(id){
 if(operator)return;
 const panel=document.getElementById('customer-request-panel-'+id);
 if(!panel)return false;
 document.querySelectorAll('[data-customer-request]').forEach(card=>{
  const open=card.dataset.customerRequest===id;
  const toggle=card.querySelector('[data-request]');
  const cardPanel=card.querySelector('.customer-request-panel');
  toggle.setAttribute('aria-expanded',String(open));
  card.classList.toggle('request-open',open);
  cardPanel.hidden=!open;
  card.querySelector('.customer-request-action').textContent=open?'Ocultar detalles':'Ver propuestas y detalles';
 });
 panel.appendChild($('#detail'));
 return true;
}
