function context(r){const req=r.request_data||{},requirements=String(req.requirements||'').trim(),notes=String(req.notes||'').trim();return `<p>${escape(events[req.event_type]||req.event_type)} · ${escape(req.location)} · ${escape(dateMX(req.event_date))}</p>${requirements?`<div class="request-field"><b>Qué te gustaría incluir</b><p>${escape(requirements)}</p></div>`:''}${notes?`<div class="request-field"><b>Algo más que debamos saber</b><p>${escape(notes)}</p></div>`:''}<span class="status">${escape(states[r.status]||r.status)}</span>`;}
async function detail(id,options={}){rememberDisclosures();const version=++loadVersion;const data=await rpc('planea_get_request',{p_request:id,p_operator:operator});if(version!==loadVersion)return;active=id;selection=null;await contactState(data,id);if(version!==loadVersion)return;rememberActive(id);const el=$('#detail');el.hidden=false;if(operator){data.candidate_map=await rpc('planea_provider_candidate_map_v1',{p_request:id});data.notification_contacts=await rpc('planea_operator_notification_contacts_v1',{p_request:id});if(version!==loadVersion)return;if(!attachOperatorRequest(id)){el.hidden=true;return;}await renderOperations(data);}else{if(!attachCustomerRequest(id)){el.hidden=true;return;}renderCustomer(data);}if(options.scroll!==false)el.scrollIntoView({behavior:'auto',block:'nearest'});}
