// Tab-scoped encrypted draft, two-hour lifetime, account-bound after authentication.
// Non-extractable key stays in IndexedDB; request fields never enter a URL or localStorage.
const draftName='planea-intake-v1';let draft=null,draftTimer,draftWrite=Promise.resolve();
async function draftKey(create=false){
 const id=sessionStorage.getItem(draftName+'-key')||(create?crypto.randomUUID():null);if(!id)return null;
 const db=await new Promise((resolve,reject)=>{const q=indexedDB.open('planea-private-drafts',1);q.onupgradeneeded=()=>q.result.createObjectStore('keys');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});
 try{let key=await new Promise((resolve,reject)=>{const q=db.transaction('keys').objectStore('keys').get(id);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});if(!key&&create){key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);await new Promise((resolve,reject)=>{const tx=db.transaction('keys','readwrite');tx.objectStore('keys').put(key,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});sessionStorage.setItem(draftName+'-key',id);}return key;}finally{db.close();}
}
async function clearDraft(){clearTimeout(draftTimer);await draftWrite.catch(()=>{});const id=sessionStorage.getItem(draftName+'-key');sessionStorage.removeItem(draftName);sessionStorage.removeItem(draftName+'-key');draft=null;if(id){const db=await new Promise((resolve,reject)=>{const q=indexedDB.open('planea-private-drafts',1);q.onupgradeneeded=()=>q.result.createObjectStore('keys');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});try{await new Promise((resolve,reject)=>{const tx=db.transaction('keys','readwrite');tx.objectStore('keys').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}}}
async function saveDraft(){if(!$('#intake'))return;const fields=formData($('#intake'));draft={...draft,fields,owner:currentUser,expires:Date.now()+7200000};const iv=crypto.getRandomValues(new Uint8Array(12)),key=await draftKey(true),body=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(draft)));sessionStorage.setItem(draftName,JSON.stringify({iv:Array.from(iv),body:Array.from(new Uint8Array(body))}));}
function queueDraft(){draftWrite=draftWrite.catch(()=>{}).then(saveDraft);return draftWrite;}
async function restoreDraft(){try{const raw=sessionStorage.getItem(draftName);if(!raw)return;const saved=JSON.parse(raw),key=await draftKey();if(!key)throw Error();draft=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(saved.iv)},key,new Uint8Array(saved.body))));if(draft.expires<Date.now()||(draft.owner&&draft.owner!==currentUser))return await clearDraft();for(const [k,v]of Object.entries(draft.fields||{})){if($('#intake').elements[k])$('#intake').elements[k].value=v;}if(serviceSelect&&serviceOther){serviceOther.hidden=serviceSelect.value!=='Otro';serviceOther.required=!serviceOther.hidden;}authRequested=!!draft.authRequested;if(currentUser&&!draft.owner){draft.owner=currentUser;await queueDraft();}}catch(_){await clearDraft();message('El borrador no está disponible en esta sesión. Completa el formulario para continuar.',true);}}
function rememberActive(id){try{sessionStorage.setItem('planea-active-v1',JSON.stringify({owner:currentUser,operator,id}));}catch(_){}}
async function contactState(data,id){const result=await client.rpc('planea_contact_requests_v1',{p_request:id,p_operator:operator});if(result.error){if(!['PGRST202','42883'].includes(result.error.code))throw new Error('No pudimos verificar las solicitudes de contacto. Actualiza antes de continuar.');data.reply_evidence=false;data.contact_requests=[];data.capabilities={...data.capabilities,contact_request:false};return;}data.reply_evidence=result.data.reply_evidence===true;data.contact_requests=result.data.requests;data.capabilities={...data.capabilities,contact_request:result.data.enabled===true};}
function parsePackage(text){const raw=String(text).trim();if(new TextEncoder().encode(raw).length>131072)throw new Error('El paquete es demasiado grande. Importa menos respuestas por vez.');const fenced=raw.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);return JSON.parse(fenced?fenced[1]:raw);}
if($('#intake')){
 $('#intake').addEventListener('input',()=>{queueDraft().catch(()=>message('No se pudo guardar el borrador en este navegador. Conserva esta pestaña abierta.',true));});
 $('#google').addEventListener('click',e=>{e.preventDefault();const target=e.currentTarget.href;run(async()=>{draft={...draft,authRequested:true};await queueDraft();location.assign(target);});});
 $('#intake').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;run(()=>lock(f,async()=>{const auth=await client.auth.getSession();if(auth.error)throw auth.error;if((auth.data.session?.user?.id||null)!==currentUser){await clearDraft();f.reset();await session();throw new Error('La cuenta cambió. Completa o revisa una nueva solicitud con la cuenta actual.');}await queueDraft();const x=formData(f);if(x.service_category==='Otro'){x.service_category=String(x.service_category_other||'').trim();if(!x.service_category)throw new Error('Escribe el servicio que necesitas.');}delete x.service_category_other;for(const k of ['budget_min','budget_max']){if(x[k]==='')delete x[k];else x[k]=Number(x[k]);}if(x.budget_min!=null&&x.budget_max!=null&&x.budget_min>x.budget_max)throw new Error('El presupuesto desde no puede ser mayor que el presupuesto hasta.');if(!currentUser){authRequested=true;draft.authRequested=true;await queueDraft();const authCard=$('#auth');authCard.hidden=false;feedbackContext={element:authCard,id:'auth'};message('Tu borrador está guardado en esta pestaña. Aún no se ha enviado.');authCard.focus({preventScroll:true});authCard.scrollIntoView({behavior:'auto',block:'start'});return;}const event=new URLSearchParams(location.search).get('event');const fingerprint=JSON.stringify({data:x,event:event||null});if(draft.fingerprint!==fingerprint){draft.fingerprint=fingerprint;draft.key=crypto.randomUUID();}await queueDraft();const id=await rpc('planea_submit_request',{p_data:x,p_key:draft.key,p_event:event||null});await clearDraft();f.reset();if(serviceSelect&&serviceOther){serviceOther.hidden=true;serviceOther.required=false;}await refresh();await detail(id);message('Recibimos tu solicitud. Aquí podrás seguir su avance.');if(!operator&&window.SemblanziaPlaneaInvitationPromo)void window.SemblanziaPlaneaInvitationPromo.open().catch(()=>{});}));});
}
async function session(){const {data,error}=await client.auth.getSession();if(error)throw error;currentUser=data.session?.user?.id||null;const signed=!!currentUser; $('#signout').hidden=!signed; if(!operator&&$('#customer-signin'))$('#customer-signin').hidden=signed;if(operator){$('#auth').hidden=signed;$('#operator').hidden=true;if(signed){if(!await rpc('planea_operator_status',{}))throw new Error('Tu cuenta no está autorizada para operar PLANEA.');$('#operator').hidden=false;await refresh();}}else{$('#customer').hidden=false;await restoreDraft();$('#auth').hidden=signed||!authRequested;if($('#customer-signin'))$('#customer-signin').setAttribute('aria-expanded',String(!$('#auth').hidden));if($('#saved-requests'))$('#saved-requests').hidden=!signed;if($('#submit-intake'))$('#submit-intake').textContent=signed?'Enviar mi solicitud':'Continuar para guardar mi solicitud';if(signed)await refresh();}if(signed){try{const saved=JSON.parse(sessionStorage.getItem('planea-active-v1'));if(saved?.owner===currentUser&&saved.operator===operator)await detail(saved.id,{scroll:false});}catch(_){sessionStorage.removeItem('planea-active-v1');}}
 // Do not automatically invoke a verifier on operator login. TEST v6 requires
 // an exact fresh job/request pair and must never claim from a shared queue.

}
if(client.auth.onAuthStateChange)client.auth.onAuthStateChange((_event,next)=>{const owner=next?.user?.id||null;if(_event==='INITIAL_SESSION'||owner===currentUser||(!currentUser&&owner&&authRequested&&!draft?.owner))return;setTimeout(()=>run(async()=>{await clearDraft();$('#intake')?.reset();$('#detail').hidden=true;active=null;sessionStorage.removeItem('planea-active-v1');await session();}),0);});
// Refresh canonical intent on tab return and periodically while this request is visible.
async function synchronizeCustomer(){if(operator||!active||pendingActions||document.visibilityState==='hidden')return;const request=active;try{const data=await rpc('planea_get_request',{p_request:request,p_operator:false});await contactState(data,request);if(request!==active||pendingActions)return;if(customerRevision(data)!==customerSnapshot){rememberDisclosures();selection=null;renderCustomer(data);message('Actualizamos tu solicitud con la selección guardada. Revisa la propuesta antes de autorizar una conexión.');}}catch(e){const consent=$('#contact-consent');if(consent)consent.checked=false;message('No pudimos verificar tu selección. Actualiza la solicitud antes de continuar.',true);}}
window.addEventListener('focus',synchronizeCustomer);document.addEventListener('visibilitychange',synchronizeCustomer);setInterval(synchronizeCustomer,15000);
run(session);
